use Illuminate\Support\Facades\DB;
use Carbon\Carbon;

$oneYearAgo = Carbon::now()->subYear()->toDateTimeString();

$activos = Activo::whereIn('id', function ($query) use ($oneYearAgo) {
    $query->select('activo_id')
        ->from('asignaciones')
        ->whereNull('fecha_retorno')
        ->where('fecha_asignacion', '<', $oneYearAgo)
        ->whereNotExists(function ($subquery) {
            $subquery->select(DB::raw(1))
                ->from('asignaciones as a2')
                ->whereRaw('a2.activo_id = asignaciones.activo_id')
                ->whereNull('a2.fecha_retorno')
                ->whereRaw('a2.fecha_asignacion > asignaciones.fecha_asignacion');
        });
})->whereIn('id', function ($query) {
    $query->select('activo_id')
        ->from('asignaciones')
        ->groupBy('activo_id', 'ubicacion_id')
        ->havingRaw('COUNT(*) >= 2');
})->get();
